#!/usr/bin/env bash
# Strings, arrays, maps, classes, interfaces, closures, nullable values and `when`
# give the same results under `#` (the evaluator) as in the program's own code.
# tests/cases/lang-parity/*.ab are generated by tools/gen-lang-parity.py; each runs
# its cases both ways and exits 42 when every pair of results matches. A copy with
# one staged case changed must fail (the harness can see a difference).
set -euo pipefail

compiler=${1:-build/ablac.bin}
project_root=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
output_directory="$project_root/build/lang-parity"
mkdir -p "$output_directory"

for source in "$project_root"/tests/cases/lang-parity/*.ab; do
    name=$(basename "$source" .ab)
    "$compiler" build "$source" -o "$output_directory/$name" --fast --no-cache
    set +e
    "$output_directory/$name"
    status=$?
    set -e
    [[ $status -eq 42 ]] || { echo "lang-parity: $name differs" >&2; exit 1; }
done

# Negative control, per file: a copy whose staged first case returns one string more must
# fail and say so (a file whose staged side stopped being compared would pass otherwise).
for source in "$project_root"/tests/cases/lang-parity/*.ab; do
    name=$(basename "$source" .ab)
    mutated="$output_directory/mutated-$name.ab"
    awk '/^compile fun .*C\(\): array<string> \{$/ && !done { print; getline; print; print "    out.append(\"mutation\")"; done = 1; next } { print }' \
        "$source" > "$mutated"
    cmp -s "$mutated" "$source" &&
        { echo "lang-parity: the negative control changed nothing in $name" >&2; exit 1; }
    "$compiler" build "$mutated" -o "$output_directory/mutated-$name" --fast --no-cache
    set +e
    "$output_directory/mutated-$name" > "$output_directory/mutated-$name.log" 2>&1
    status=$?
    set -e
    [[ $status -eq 1 ]] && grep -q 'sizes' "$output_directory/mutated-$name.log" ||
        { echo "lang-parity: the negative control was not caught in $name" >&2; exit 1; }
done
echo "lang parity: the language's values and control flow match between the evaluator and native code"
